import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const deferred = () => { let resolve; const promise = new Promise(r => { resolve = r; }); return { promise, resolve }; };
const pending = new Map();
const feed = createProgressFeed({ initialPacket: 'initial', decode(packet) { return pending.get(packet)?.promise ?? packet; } });
const records = [], shown = [], deltas = [], queues = [];
const stopTelemetry = collectProgressTelemetry(feed, frame => deltas.push(frame));
const workspace = createTransferWorkspace({ transport() {}, onCancel() {}, record: x => queues.push(x), showQueued() {}, recordProgress: x => records.push(x), showProgress: x => shown.push(x) });
workspace.select({ id: 'file', progressFeed: feed });
assert.deepEqual(shown.map(x => x.frame), ['initial']);
assert.deepEqual(deltas, []);
pending.set('old', deferred()); pending.set('new', deferred());
feed.emit('old'); feed.emit('new');
pending.get('new').resolve('new'); await Promise.resolve();
pending.get('old').resolve('old'); await Promise.resolve();
assert.deepEqual(shown.map(x => x.frame), ['initial', 'new']);
assert.deepEqual(records.map(x => x.frame), ['initial', 'new', 'old']);
assert.deepEqual(deltas, ['new', 'old']);
feed.emit('later');
assert.equal(shown.at(-1).frame, 'later');
workspace.hide();
feed.emit('hidden');
assert.equal(shown.at(-1).frame, 'later');
workspace.select({ id: 'file', progressFeed: feed });
assert.equal(shown.at(-1).frame, 'initial');
assert.deepEqual(queues.map(x => Object.keys(x)), [['fileId','attemptId','visitId','kind'], ['fileId','attemptId','visitId','kind']]);
workspace.dispose(); stopTelemetry();
console.log('progress checks passed');
EOF"

